#include <stdio.h>
#include <stdlib.h>
#include <inttypes.h>
#include "fftools/sync_queue.c"
int main(void){int n,ops;int64_t buffer;av_log_set_level(AV_LOG_QUIET);while(scanf("%d %d %"SCNd64,&n,&ops,&buffer)==3){if(n<1||n>32||ops<0||ops>10000)return 2;SyncQueue *sq=sq_alloc(SYNC_QUEUE_FRAMES,buffer,NULL);if(!sq)return 3;for(int i=0;i<n;i++){int limiting;if(scanf("%d",&limiting)!=1||sq_add_stream(sq,limiting)!=i)return 4;}AVFrame *frame=av_frame_alloc();printf("[");for(int op=0;op<ops;op++){char cmd;int index,ret;if(scanf(" %c %d",&cmd,&index)!=2)return 5;if(op)putchar(',');printf("{\"result\":");if(cmd=='s'){int value,num,den;int64_t pts,duration;if(scanf("%"SCNd64" %"SCNd64" %d %d %d",&pts,&duration,&num,&den,&value)!=5)return 6;frame->format=AV_PIX_FMT_GRAY8;frame->width=frame->height=1;frame->pts=pts;frame->duration=duration;frame->time_base=(AVRational){num,den};if(av_frame_get_buffer(frame,32)<0)return 7;frame->data[0][0]=value;ret=sq_send(sq,index,SQFRAME(frame));printf("%d",ret);av_frame_unref(frame);}else if(cmd=='e'){printf("%d",sq_send(sq,index,SQFRAME(NULL)));}else if(cmd=='l'){uint64_t limit;if(scanf("%"SCNu64,&limit)!=1)return 8;sq_limit_frames(sq,index,limit);printf("0");}else if(cmd=='r'){ret=sq_receive(sq,index,SQFRAME(frame));printf("{\"code\":");if(ret==AVERROR(EAGAIN))printf("\"again\"");else printf("%d",ret);if(ret>=0){printf(",\"frame\":{\"pts\":");if(frame->pts==AV_NOPTS_VALUE)printf("null");else printf("\"%"PRId64"\"",frame->pts);printf(",\"duration\":\"%"PRId64"\",\"timeBase\":{\"num\":\"%d\",\"den\":\"%d\"},\"value\":%d}",frame->duration,frame->time_base.num,frame->time_base.den,frame->data[0][0]);av_frame_unref(frame);}putchar('}');}else return 9;
 printf(",\"state\":{\"finished\":%s,\"head\":%d,\"headFinished\":%d,\"streams\":[",sq->finished?"true":"false",sq->head_stream,sq->head_finished_stream);size_t total=0;for(int i=0;i<n;i++){SyncQueueStream *st=&sq->streams[i];size_t queued=av_container_fifo_can_read(st->fifo);total+=queued;if(i)putchar(',');printf("{\"limiting\":%s,\"finished\":%s,\"head\":\"%"PRId64"\",\"timeBase\":{\"num\":\"%d\",\"den\":\"%d\"},\"sent\":\"%"PRIu64"\",\"max\":\"%"PRIu64"\",\"queued\":%zu}",st->limiting?"true":"false",st->finished?"true":"false",st->head_ts,st->tb.num,st->tb.den,st->frames_sent,st->frames_max,queued);}printf("],\"residentBytes\":%zu,\"queued\":%zu}}",total,total);
 }puts("]");av_frame_free(&frame);sq_free(&sq);}return 0;}
